[DataMemberAttribute("METItemStatus"),
 SysOperationGroupMemberAttribute("Parameters"),
 SysOperationDisplayOrderAttribute("1")]    
public METItemStatus parmMETItemStatus(METItemStatus _metItemStatus = metItemStatus)
{
